import XCTest

@testable import CodeConnect
@testable import CodeConnectKit

/// **The owner's other computers, joined without a code**, against the daemon's
/// own bytes.
///
/// `peers.json` is what ccd emits (`fixtures/wire/`, regenerated by the
/// protocol crate's tests and copied here byte for byte): the frame for a
/// running tailnet, for Tailscale installed but not running, and for none.
@MainActor
final class PeerDirectoryTests: XCTestCase {

    private func frame(_ key: String) throws -> PeerDirectory {
        let url = try XCTUnwrap(Bundle(for: type(of: self)).url(forResource: "peers", withExtension: "json"))
        let wire = try XCTUnwrap(
            try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: url)).objectValue)
        let value = try XCTUnwrap(wire[key], "no \(key) in peers.json")
        guard
            case .peers(let directory) = try JSONDecoder().decode(
                ServerMessage.self, from: Data(value.canonicalJSONString.utf8))
        else {
            XCTFail("\(key) is not a peers frame")
            throw CancellationError()
        }
        return directory
    }

    func testEveryPeersFrameTheDaemonEmitsDecodes() throws {
        let running = try frame("running")
        XCTAssertEqual(running.tailnet, "running")
        XCTAssertEqual(running.login, "owner@example.com")
        XCTAssertFalse(running.tagged)
        XCTAssertEqual(running.computers.map(\.name), ["laptop"])
        XCTAssertEqual(running.computers.map(\.host), ["laptop.tail0000.ts.net"])
        XCTAssertEqual(running.computers.map(\.port), [8787])

        for key in ["not_running", "not_installed"] {
            let stopped = try frame(key)
            XCTAssertEqual(stopped.tailnet, key)
            XCTAssertNil(stopped.login)
            XCTAssertEqual(stopped.computers, [])
        }
    }

    /// The hello the daemon checks against Tailscale carries neither credential:
    /// a blank token would be taken as the credential and refused.
    func testATailscaleHelloCarriesNoCredential() throws {
        let data = try JSONEncoder().encode(
            ClientMessage.hello(credential: .tailnet, clientID: "device", clientName: "iPhone"))
        let object = try XCTUnwrap(try JSONSerialization.jsonObject(with: data) as? [String: Any])
        XCTAssertEqual(object["type"] as? String, "hello")
        XCTAssertNil(object["token"])
        XCTAssertNil(object["pairing_code"])
        XCTAssertEqual(object["client_id"] as? String, "device")
    }

    /// What Tailscale lets in is paid for with a device token; the hello that
    /// asked is never a pairing.
    func testATailscaleHelloIsNeverStored() {
        let store = PairingStore(ephemeral: true)
        store.save(
            DaemonEndpoint(host: "laptop.tail0000.ts.net", port: 8787, credential: .tailnet, useTLS: false),
            id: "laptop")
        XCTAssertEqual(store.machines, [])

        let joined = DaemonEndpoint(
            host: "laptop.tail0000.ts.net", port: 8787, credential: .tailnet, useTLS: false)
        store.adopt(deviceToken: "device-token", from: joined, id: "laptop")
        XCTAssertEqual(store.machines.map(\.endpoint.token), ["device-token"])
    }

    /// Each daemon's word on its own computer's Tailscale stays with that computer: a second computer's frame never
    /// speaks for the first.
    func testEachComputersTailscaleIsKeptOnItsOwnModel() throws {
        let running = try frame("running")
        let stopped = try frame("not_running")
        let models = (0..<2).map { _ in
            AppModel(
                cache: EventCache(root: temporaryCache()),
                codexSpentLedger: CodexSpentLedger(defaults: UserDefaults(suiteName: "cc.tests.\(UUID().uuidString)")!))
        }
        models[0].connection.injectForTesting(.peers(running))
        models[1].connection.injectForTesting(.peers(stopped))
        XCTAssertEqual(models[0].tailnet, running)
        XCTAssertEqual(models[1].tailnet, stopped)
    }

    func testAListedComputerIsJoinedOnceAndAPairedOneNotAtAll() throws {
        let running = try frame("running")
        let pairing = PairingStore(ephemeral: true)
        let machines = Machines(pairing: pairing, cache: EventCache(root: temporaryCache()))
        machines.join(running)
        machines.join(running)
        XCTAssertEqual(machines.joining.map(\.computer.host), ["laptop.tail0000.ts.net"])

        let paired = PairingStore(ephemeral: true)
        paired.save(
            DaemonEndpoint(host: "LAPTOP.tail0000.ts.net", port: 8787, credential: .token("t"), useTLS: false),
            id: "laptop")
        let fleet = Machines(pairing: paired, cache: EventCache(root: temporaryCache()))
        fleet.join(running)
        XCTAssertEqual(fleet.joining.count, 0, "a computer paired under the same address is not dialled again")

        machines.pair(withQR: PairingQRPayload(host: "laptop.tail0000.ts.net", port: 8787, code: "ABCD2345"))
        XCTAssertEqual(machines.joining.count, 0, "paired by code, it is no longer joined from the list")
        machines.cancelPairing()
    }

    /// P1c-6: a computer removed from this device stays removed after a
    /// relaunch — no daemon's list brings it back — until it is paired by code.
    func testARemovedComputerStaysRemovedAfterARelaunch() throws {
        let prefix = "declined-\(UUID().uuidString)-"
        addTeardownBlock {
            _ = Keychain.delete(account: prefix + "machines")
            _ = Keychain.delete(account: prefix + "declined")
        }
        let running = try frame("running")
        let host = try XCTUnwrap(running.computers.first?.host)

        let before = PairingStore(keychainPrefix: prefix)
        before.save(DaemonEndpoint(host: host, port: 8787, credential: .token("t"), useTLS: false), id: "laptop")
        XCTAssertEqual(before.machines.map(\.id), ["laptop"])
        Machines(pairing: before, cache: EventCache(root: temporaryCache())).removeMachine(id: "laptop")

        let relaunched = PairingStore(keychainPrefix: prefix)
        XCTAssertEqual(relaunched.machines, [])
        let machines = Machines(pairing: relaunched, cache: EventCache(root: temporaryCache()))
        machines.join(running)
        XCTAssertEqual(machines.joining.count, 0, "the removed computer is not dialled")

        machines.pair(withQR: PairingQRPayload(host: host, port: 8787, code: "ABCD2345"))
        machines.cancelPairing()
        XCTAssertFalse(PairingStore(keychainPrefix: prefix).isDeclined(host: host), "pairing by code wants it back")
    }

    /// The computer's daemon and every address it was known by: a removed
    /// computer listed under another of its names stays out too.
    func testARemovedComputerIsKnownByItsDaemonAndEveryAddress() {
        let store = PairingStore(ephemeral: true)
        store.decline(daemonID: "daemon-1", host: "100.64.0.7")
        store.decline(daemonID: "daemon-1", host: "Laptop.tail0000.ts.net")
        XCTAssertEqual(store.declined.count, 1)
        XCTAssertTrue(store.isDeclined(host: "100.64.0.7"))
        XCTAssertTrue(store.isDeclined(host: "laptop.tail0000.ts.net"))
        XCTAssertTrue(store.isDeclined(daemonID: "daemon-1"))

        store.undecline(daemonID: "daemon-1")
        XCTAssertEqual(store.declined, [])
    }

    /// A refusal says how to add the computer by its code, in the words of the
    /// device reading it: a Mac has no camera, and "this computer" there is the
    /// Mac itself.
    func testACodeIsAskedForInTheReadersOwnWords() {
        XCTAssertEqual(HostDevice.iPhone.addWithCode, "Scan this computer's code to add it.")
        XCTAssertEqual(
            HostDevice.iPhone.codeAgain,
            "Show a new code on your computer and scan it (codeconnect.sh/support shows how).")
        XCTAssertEqual(HostDevice.mac.pairingComputer("Your computer"), "That computer")
        XCTAssertEqual(HostDevice.mac.computer("the computer"), "the agent's computer")
        XCTAssertEqual(HostDevice.iPhone.pairingComputer("your computer"), "your computer")
        for sentence in [HostDevice.mac.addWithCode, HostDevice.mac.codeAgain] {
            XCTAssertFalse(sentence.lowercased().contains("scan"), sentence)
            XCTAssertFalse(sentence.contains("this computer"), sentence)
        }
        XCTAssertEqual(ConnectionError.notAdmitted.localizedDescription, HostDevice.current.addWithCode)
        XCTAssertTrue(
            ConnectionError.rejectedPairingCode.localizedDescription.hasSuffix(HostDevice.current.codeAgain))
    }

    private func temporaryCache() -> URL {
        let url = FileManager.default.temporaryDirectory.appendingPathComponent(
            "peers-\(UUID().uuidString)", isDirectory: true)
        addTeardownBlock { try? FileManager.default.removeItem(at: url) }
        return url
    }
}
